begin;
select no_plan();
select is((select count(*) from private.proposal_templates where template_kind='official_starter'),8::bigint,'eight permanent official identities');
select is((select count(*) from public.proposals),0::bigint,'catalog creates no fictional Projects');
select is((select count(*) from public.profiles),0::bigint,'catalog creates no human or Auth profiles');
select ok((select bool_and(source_proposal_id is null and original_creator_profile_id is null) from private.proposal_templates where template_kind='official_starter'),'organization provenance has no source or human');
select ok((select bool_and(relrowsecurity) from pg_class where oid in ('private.official_starter_template_content'::regclass,'private.official_starter_template_reviews'::regclass)),'curation internals enable RLS');
select ok(not exists(select 1 from unnest(array['anon','authenticated','service_role']) actor cross join unnest(array['private.official_starter_template_content','private.official_starter_template_reviews']) obj where has_table_privilege(actor,obj,'SELECT,INSERT,UPDATE,DELETE')),'no API roles can read or curate raw content/reviews');
select ok(not exists(select 1 from unnest(array['anon','authenticated','service_role']) actor where has_function_privilege(actor,'private.provision_official_starter_template(uuid,text,text,jsonb,text,boolean)','EXECUTE')),'provisioning is database-owner only');
select set_config('test.official',(select id::text from private.proposal_templates where starter_key='repair'),true);
select set_config('test.token',(select content_version from public.get_public_proposal_template_v2(current_setting('test.official')::uuid)),true);
select set_config('test.rawhash',(select private.proposal_template_content_version(content) from private.official_starter_template_content where template_id=current_setting('test.official')::uuid),true);
set local role anon;
select is((select count(*) from public.list_public_proposal_templates_v2()),8::bigint,'actual public v2 catalog returns eight');
select ok((select bool_and(is_official and creator_display_name='Planets Community Official') from public.list_public_proposal_templates_v2()),'official metadata authoritative');
select is((select count(*) from public.list_public_proposal_templates()),0::bigint,'legacy client keeps community-only projection');
select is((select count(*) from public.get_public_proposal_template(current_setting('test.official')::uuid)),0::bigint,'legacy source detail has no fake official source');
select is((select count(*) from public.list_public_proposal_templates_v2(p_query=>'Repair Café')),1::bigint,'Italian literal title search');
select is((select count(*) from public.list_public_proposal_templates_v2(p_query=>'_%')),0::bigint,'search does not treat wildcard text as pattern');
select is((select count(*) from public.list_public_proposal_templates_v2(p_skill_ids=>array[(select id from public.skills where slug='basic-repairs')])),1::bigint,'OR skill selection filters official examples');
select throws_ok($$select public.list_public_proposal_templates_v2(p_limit=>0)$$,'22023',null,'v2 retains page validation');
select throws_ok($$select public.list_public_proposal_templates_v2(p_cursor_id=>current_setting('test.official')::uuid)$$,'22023',null,'v2 retains paired cursor validation');
select throws_ok($$select public.list_public_proposal_templates_v2(p_skill_ids=>array['ff000000-0000-4000-8000-000000000000'::uuid])$$,'22023',null,'unknown controlled skills rejected');
select is((select count(*) from public.list_public_proposal_templates_v2(p_cursor_linked_at=>(select linked_at from public.list_public_proposal_templates_v2(p_limit=>1)),p_cursor_id=>(select template_id from public.list_public_proposal_templates_v2(p_limit=>1)))),7::bigint,'paired keyset visits remaining examples exactly once');
select is((select count(*) from public.list_public_proposal_template_resource_blueprints_v2(current_setting('test.official')::uuid,current_setting('test.token'))),2::bigint,'all open reusable needs available');
select throws_ok($$select public.list_public_proposal_template_resource_blueprints_v2(current_setting('test.official')::uuid,'tw01:'||repeat('0',64))$$,'PT409',null,'blueprint drift fails loudly');
select throws_ok($$select * from private.official_starter_template_content$$,'42501',null,'anonymous cannot read private curation');
reset role;
-- Trusted test identities only, rolled back; provisioning itself creates none.
insert into auth.users(id,email) values ('ff010000-0000-4000-8000-000000000001','ost01-applicant@planets.invalid'),('ff010000-0000-4000-8000-000000000002','ost01-peer@planets.invalid'),('ff010000-0000-4000-8000-000000000003','ost01-staff@planets.invalid');
insert into public.profiles(id,display_name) select id,'Planets Community Official' from auth.users where id::text like 'ff010000%';
insert into private.moderation_staff_roles(profile_id,staff_role) values ('ff010000-0000-4000-8000-000000000003','moderator');
select set_config('request.jwt.claim.sub','ff010000-0000-4000-8000-000000000001',true);
set local role authenticated;
select throws_ok($$update private.proposal_templates set template_kind='official_starter'$$,'42501',null,'display-name impersonator cannot assert official status');
select throws_ok($$select private.provision_official_starter_template(current_setting('test.official')::uuid,'repair',null,'{}','Malicious client curation')$$,'42501',null,'authenticated provisioning denied');
select throws_ok($$select public.get_own_proposal_template_baseline('ff010000-0000-4000-8000-000000000001',current_setting('test.official')::uuid)$$,'42501',null,'organization has no fabricated saved draft');
select set_config('test.draft',(select proposal_id::text from public.create_proposal_draft_from_template('ff010000-0000-4000-8000-000000000001',current_setting('test.official')::uuid,current_setting('test.token'),'ff020000-0000-4000-8000-000000000001')),true);
select is((select outcome from public.create_proposal_draft_from_template('ff010000-0000-4000-8000-000000000001',current_setting('test.official')::uuid,current_setting('test.token'),'ff020000-0000-4000-8000-000000000001')),'recovered','exact retry returns same acceptance');
select set_config('test.case',(select case_id::text from public.submit_moderation_report('ff010000-0000-4000-8000-000000000001','ff030000-0000-4000-8000-000000000001','other','Review this official example safely.','proposal_template',current_setting('test.official')::uuid,null,null)),true);
reset role;
select is((select lifecycle_state from public.proposals where id=current_setting('test.draft')::uuid),'draft','copy remains private editable draft');
select ok((select starts_at is null and ends_at is null and country_code is null and locality is null and published_at is null from public.proposals where id=current_setting('test.draft')::uuid),'no source dates/location/history inherited');
select is((select count(*) from public.proposal_skills where proposal_id=current_setting('test.draft')::uuid),2::bigint,'controlled skills copied');
select is((select count(*) from public.project_resource_needs where project_id=current_setting('test.draft')::uuid),2::bigint,'fresh independent needs copied');
select is((select count(*) from public.project_covers where project_id=current_setting('test.draft')::uuid),0::bigint,'illustration not assigned as user-owned cover');
select ok((select source_proposal_id is null from private.proposal_template_applications where proposal_id=current_setting('test.draft')::uuid),'receipt preserves organization provenance');
select ok((select subject_profile_id is null and template_source_proposal_id is null from private.moderation_cases where id=current_setting('test.case')::uuid),'report does not accuse an invented human or Project');
select set_config('request.jwt.claim.sub','ff010000-0000-4000-8000-000000000002',true);
set local role authenticated;
select is((select count(*) from public.get_own_proposal_template_application('ff010000-0000-4000-8000-000000000002','ff020000-0000-4000-8000-000000000001')),0::bigint,'peer cannot recover another applicant receipt');
select is((select outcome from public.create_proposal_draft_from_template('ff010000-0000-4000-8000-000000000002',current_setting('test.official')::uuid,current_setting('test.token'),'ff020000-0000-4000-8000-000000000001')),'created','same request key is applicant-scoped');
reset role;
-- Exact reviewed provisioning is harmless; stale edits cannot overwrite drift.
select lives_ok($$select private.provision_official_starter_template(t.id,t.starter_key,null,c.content,'OST01 exact repeat verification') from private.proposal_templates t join private.official_starter_template_content c on c.template_id=t.id where t.starter_key='repair'$$,'repeat provisioning is no-op');
select is((select count(*) from private.official_starter_template_reviews),8::bigint,'repeat creates no extra review');
select throws_ok($$select private.provision_official_starter_template(t.id,t.starter_key,null,jsonb_set(c.content,'{summary}','"Changed review"'),'OST01 stale update verification') from private.proposal_templates t join private.official_starter_template_content c on c.template_id=t.id where t.starter_key='repair'$$,'PT409',null,'unreviewed drift rejected');
select lives_ok($$select private.provision_official_starter_template(t.id,t.starter_key,current_setting('test.rawhash'),jsonb_set(c.content,'{summary}','"Changed review"'),'OST01 approved update verification') from private.proposal_templates t join private.official_starter_template_content c on c.template_id=t.id where t.starter_key='repair'$$,'reviewed edit succeeds');
select isnt((select content_version from public.get_public_proposal_template_v2(current_setting('test.official')::uuid)),current_setting('test.token'),'edit changes token');
select set_config('request.jwt.claim.sub','ff010000-0000-4000-8000-000000000001',true);
set local role authenticated;
select throws_ok($$select public.create_proposal_draft_from_template('ff010000-0000-4000-8000-000000000001',current_setting('test.official')::uuid,current_setting('test.token'),'ff020000-0000-4000-8000-000000000002')$$,'PT409',null,'new application rejects stale token');
select is((select outcome from public.create_proposal_draft_from_template('ff010000-0000-4000-8000-000000000001',current_setting('test.official')::uuid,current_setting('test.token'),'ff020000-0000-4000-8000-000000000001')),'recovered','accepted old version remains recoverable');
reset role;
select set_config('request.jwt.claim.sub','ff010000-0000-4000-8000-000000000003',true);
set local role authenticated;
select is((select subject_display_name from public.list_moderation_cases('ff010000-0000-4000-8000-000000000003')),'Planets Community Official','staff queue includes organization report');
select is((select subject_display_name from public.get_moderation_case_detail('ff010000-0000-4000-8000-000000000003',current_setting('test.case')::uuid)),'Planets Community Official','staff detail includes organization report');
select ok((select content_changed from public.get_moderation_case_template('ff010000-0000-4000-8000-000000000003',current_setting('test.case')::uuid)),'staff sees edited report token');
select throws_ok($$select public.remove_moderation_case_template('ff010000-0000-4000-8000-000000000003',current_setting('test.case')::uuid,current_setting('test.official')::uuid,'ff040000-0000-4000-8000-000000000001',current_setting('test.token'),'Reviewed unsafe official content')$$,'PT409',null,'removal retains reviewed-token guard');
select is((select outcome from public.remove_moderation_case_template('ff010000-0000-4000-8000-000000000003',current_setting('test.case')::uuid,current_setting('test.official')::uuid,'ff040000-0000-4000-8000-000000000002',(select current_content_version from public.get_moderation_case_template('ff010000-0000-4000-8000-000000000003',current_setting('test.case')::uuid)),'Reviewed unsafe official content')),'removed','canonical moderation can remove official example');
reset role;
select is((select count(*) from public.get_public_proposal_template_v2(current_setting('test.official')::uuid)),0::bigint,'removed example unavailable by exact ID');
select is((select count(*) from public.list_public_proposal_template_resource_blueprints_v2(current_setting('test.official')::uuid,current_setting('test.token'))),0::bigint,'removed blueprint private');
select set_config('request.jwt.claim.sub','ff010000-0000-4000-8000-000000000001',true);
set local role authenticated;
select is((select outcome from public.create_proposal_draft_from_template('ff010000-0000-4000-8000-000000000001',current_setting('test.official')::uuid,current_setting('test.token'),'ff020000-0000-4000-8000-000000000001')),'recovered','accepted receipt survives removal');
reset role;
select lives_ok($$select private.provision_official_starter_template(t.id,t.starter_key,private.proposal_template_content_version(c.content),c.content,'OST01 administrative retirement',true) from private.proposal_templates t join private.official_starter_template_content c on c.template_id=t.id where t.starter_key='dinner'$$,'database-owner retirement succeeds');
select is((select count(*) from public.list_public_proposal_templates_v2()),6::bigint,'moderation removal and curation retirement both hide new use');
select throws_ok($$select private.provision_official_starter_template(t.id,t.starter_key,private.proposal_template_content_version(c.content),c.content,'OST01 denied reactivation',false) from private.proposal_templates t join private.official_starter_template_content c on c.template_id=t.id where t.starter_key='dinner'$$,'PT409',null,'retirement terminal');
select * from finish();
rollback;
